import json,hashlib
p='/workspace/scratch/volume4/batch309-318.json';d=json.load(open(p))
def page(n,rows):
 ps=[]
 for i,(ar,ru) in enumerate(rows,1):
  sid=f'v4-p{n}-{i:02}';ps.append(dict(id=sid,ar=ar,sha256=hashlib.sha256(ar.encode()).hexdigest(),witness='uploaded_2019_control_pdf',source_complete=True))
  d['units'].append(dict(id=sid+'-ru',source_ids=[sid],printed_pages=[n],ar=ar,ru=ru,draft_status='draft',print_collation='control_image_read',independent_human_review=False))
 d['pages'].append(dict(printed_page=n,pdf_leaf=n,witness_status='control_print_visually_read',publisher_footnote_text_imported=False,paragraphs=ps))
page(313,[
('سرير مملكته الذي هو عرشه المجيد.', 'престолом Своего царства — Его славным Троном.'),
('فمتى قام بالقلب تعظيم الحق جل جلاله، وحسن النظر في الشواهد، والتبصر والاعتبار بها = صارت الصفات والنعوت مشهودة لقلبه قبلة له.', 'Когда в сердце утверждаются возвеличивание Истинного, велико Его величие, верное рассмотрение свидетельств, проницательное вникание и назидательное размышление о них, качества и свойства становятся созерцаемыми сердцем и направлением, к которому оно обращено.'),
('قوله: «وهي معرفة العامة التي لا تنعقد شرائط اليقين إلا بها»، لا يريد بالعامة الجهال الذين هم عوام الناس، وإنما يريد: أن هذه هي المعرفة التي وقف عندها العموم ولم يتعدوها، وأما معرفة أهل الذوق والمحبة الخاصة فأخص من هذه كما سيأتي.', 'Его слова «это познание обычных людей, без которого не складываются условия убеждённости» не означают, что речь идёт о невежественных простолюдинах. Он имеет в виду, что большинство останавливается на таком познании и не идёт дальше. Познание же людей непосредственного вкушения и особой любви более особое, чем это, как будет сказано далее.'),
('قوله: «وهي على ثلاثة أركان: إثبات الصفة باسمها من غير تشبيه...» إلى آخره. تضمن هذا ثلاثة أشياء.', 'Его слова «оно зиждется на трёх столпах: утверждении качества под его именем без уподобления…» и далее содержат три положения.'),
('أحدها: إثبات تلك الصفة، فلا يقابلها بالنفي والإنكار.', 'Первое: утверждать это качество, не встречая его отрицанием и непризнанием.'),
('الثاني: أنه لا يتعدى بها اسمها الخاص الذي سماها الله به، بل يحترم الاسم كما يحترم الصفة، فلا يعطل الصفة، ولا يغير اسمها ويعيرها اسما آخر، كما تسمي الجهمية والمعطلة سمعه وبصره وقدرته وحياته وكلامه: أعراضا، ويسمون وجهه ويده وقدمه ـ سبحانه ـ: جوارح وأبعاضا، ويسمون حكمته وغاية فعله المطلوبة به: عللا وأغراضا، ويسمون أفعاله القائمة به: حوادث، ويسمون علوه على خلقه واستواءه على عرشه: تحيزا، ويتوصلون بهذا المكر الكبار إلى نفي ما دل عليه الوحي والعقل والفطرة وآثار الصنعة من صفاته، فيسلطون هذه الأسماء التي سموها هم وآباؤهم', 'Второе: не выходить в отношении качества за пределы его особого имени, которым его назвал Аллах, и чтить имя так же, как чтят качество. Нельзя ни отрицать качество, ни изменять его имя и присваивать ему другое. Джахмиты и отрицающие качества называют Его слух, зрение, могущество, жизнь и речь «акциденциями»; Его лик, руку и стопу, пречист Он, — «органами и частями»; Его мудрость и желаемую цель Его действия — «причинами и целями»; Его действия, присущие Ему, — «возникающими событиями»; Его возвышенность над творениями и возвышение над Троном — «занятием пространства». Посредством этой великой хитрости они приходят к отрицанию Его качеств, на которые указывают откровение, разум, естество и следы творения. Они обращают эти имена, выдуманные ими и их отцами,')])
page(314,[
('على نفي صفاته وحقائق أسمائه.', 'на отрицание Его качеств и реальностей Его имён.'),
('الثالث: عدم تشبيهها بما للمخلوق، فإن الله سبحانه ليس كمثله شيء في ذاته، ولا في صفاته، ولا في أفعاله؛ فالعارفون به، المصدقون لرسله، المقرون بكماله يثبتون له الأسماء والصفات، وينفون عنه مشابهة المخلوقات، فيجمعون بين الإثبات ونفي التشبيه، وبين التنزيه وعدم التعطيل، فمذهبهم حسنة بين سيئتين، وهدى بين ضلالتين، فصراطهم صراط المنعم عليهم، وصراط غيرهم صراط المغضوب عليهم والضالين.', 'Третье: не уподоблять эти качества тому, чем обладает творение. Ведь ничто не подобно Пречистому Аллаху ни в Его Сущности, ни в Его качествах, ни в Его действиях. Познавшие Его, верящие Его посланникам и признающие Его совершенство, утверждают за Ним имена и качества и отрицают Его подобие творениям. Они соединяют утверждение с отрицанием уподобления, а признание Его пречистоты — с отказом отрицать качества. Их путь — благо между двумя видами зла и верное руководство между двумя заблуждениями. Их стезя — стезя облагодетельствованных, а стезя остальных — стезя тех, на кого пал гнев, и заблудших.'),
('قال الإمام أحمد: لا نزيل عن الله صفة من صفاته، لأجل شناعة المشنعين. وقال: التشبيه: أن تقول يد كيدي ووجه كوجهي، تعالى الله عن ذلك علوا كبيرا.', 'Имам Ахмад сказал: «Мы не устраняем ни одного из качеств Аллаха из-за поношений поносителей». И он сказал: «Уподобление — это когда ты говоришь: рука, как моя рука, и лик, как моё лицо. Аллах превыше этого великим возвышением».'),
('قوله: «والإياس من إدراك كنهها، وابتغاء تأويلها»، يعني: أن العقل قد يئس من معرفة كنه الصفة وكيفيتها، فإنه لا يعلم كيف الله إلا الله، وهذا معنى قول السلف: بلا كيف، أي بلا كيف يعقله البشر، فإن من لا تعلم حقيقة', 'Его слова «и отказе от надежды постичь их сокровенную сущность и от стремления истолковать их» означают: разум не надеется познать сокровенную сущность качества и то, каково оно. Ибо лишь Аллах знает, каков Аллах. Таков смысл слов предшественников «без “как”», то есть без такого «как», которое мог бы постичь человеческий разум. Ведь если ты не знаешь истинной')])
page(315,[
('ذاته وماهيته، كيف تعرف كيفية نعوته وصفاته؟', 'сущности и природы Его Сущности, как ты узнаешь, каковы Его свойства и качества?'),
('ولا يقدح ذلك في الإيمان بها ومعرفة معانيها، فالكيفية وراء ذلك، كما أنا نعرف معاني ما أخبر الله به من حقائق ما في اليوم الآخر، ولا نعرف حقيقة كيفيته، مع قرب ما بين المخلوق والمخلوق، فعجزنا عن معرفة كيفية الخالق وصفاته أعظم وأعظم.', 'Это не умаляет веры в них и знания их смыслов: вопрос о том, каковы они, лежит за пределами этого. Так мы знаем смыслы того, что Аллах сообщил о подлинных явлениях Последнего дня, однако не знаем, каковы они в действительности, хотя сотворённое и сотворённое близки друг другу. Тем более, неизмеримо более, мы неспособны познать, каков Творец и каковы Его качества.'),
('وكيف يطمع العقل المخلوق المحصور المحدود في معرفة كيفية من له الكمال كله، والجمال كله، والعلم كله، والقدرة كلها، والعظمة كلها، والكبرياء كلها؟! من لو كشف الحجاب عن وجهه لأحرقت سبحاته السماوات والأرض وما فيهما وما بينهما، وما وراء ذلك؛ الذي يقبض سماواته بيده، فتغيب كما تغيب الخردلة في كف أحدنا؛ الذي نسبة علوم الخلائق كلهم إلى علمه أقل من نسبة نقرة عصفور من بحار العالم؛ الذي لو أن البحر ـ يمده من بعده سبعة أبحر ـ مداد، وأشجار الأرض من حين خلقت إلى قيام الساعة أقلام = فني المداد وفنيت الأقلام ولم تنفد كلماته؛', 'Как сотворённый, стеснённый пределами и ограниченный разум может надеяться познать, каков Тот, Кому принадлежат всё совершенство, вся красота, всё знание, всё могущество, всё величие и всё величавое превосходство?! Если бы Он снял покров со Своего лика, Его сияние сожгло бы небеса и землю, всё, что в них и между ними, и всё, что за их пределами. Он сжимает Свои небеса рукой, и они скрываются, как скрывается горчичное зерно в ладони одного из нас. Знания всех творений относятся к Его знанию в ещё меньшей мере, чем то, что зачерпнул воробей клювом, — к морям мира. Если бы море, пополняемое ещё семью морями, стало чернилами, а деревья земли со времени их сотворения до наступления Часа стали перьями, чернила и перья иссякли бы, а Его слова не иссякли бы;')])
page(316,[
('الذي لو أن الخلق من أول الدنيا إلى آخرها إنسهم وجنهم وناطقهم وأعجمهم جعلوا صفا واحدا ما أحاطوا به سبحانه؛ الذي يضع السماوات على إصبع من أصابعه، والأرض على إصبع، والجبال على إصبع، والأشجار على إصبع، ثم يهزهن ثم يقول: أنا الملك.', 'если бы все творения от начала мира до его конца — люди и джинны, говорящие и бессловесные — встали в один ряд, они не объяли бы Его, пречист Он. Он кладёт небеса на один из Своих пальцев, землю — на палец, горы — на палец, деревья — на палец, затем сотрясает их и говорит: «Я — Царь».'),
('فقاتل الله الجهمية والمعطلة! أين التشبيه هاهنا؟! وأين التمثيل؟ لقد اضمحل هاهنا كل موجود سواه، فضلا عن أن يكون له ما يماثله في ذلك الكمال ويشابهه فيه، فسبحان من حجب عقول هؤلاء عن معرفته، وولاها ما تولته من وقوفها مع الألفاظ التي لا حرمة لها والمعاني التي لا حقائق لها.', 'Да поразит Аллах джахмитов и отрицающих качества! Где здесь уподобление?! Где приравнивание?! Перед этим меркнет всё существующее, кроме Него; тем более не может быть кого-либо, кто был бы равен Ему в таком совершенстве и подобен Ему в нём. Пречист Тот, Кто заслонил разум этих людей от познания Себя и предал его тому, к чему он обратился, — пребыванию со словами, не имеющими святости, и смыслами, не имеющими действительности.'),
('ولما فهمت هذه الطائفة من الصفات الإلهية ما تفهمه من صفات المخلوقين فرت إلى إنكار حقائقها وابتغاء تحريفها، وسمته تأويلا، فشبهت أولا، وعطلت ثانيا، وأساءت الظن بربها وبكتابه وبنبيه وبأتباعه.', 'Когда эта группа поняла божественные качества так, как понимает качества творений, она устремилась к отрицанию их реальностей и к их искажению, назвав это истолкованием. Так она сначала уподобила, затем отвергла качества и дурно подумала о своём Господе, Его Книге, Его пророке и последователях пророка.'),
('أما إساءة الظن بالرب تعالى، فإنها عطلت صفات كماله، ونسبته إلى أنه أنزل كتابا مشتملا على ما ظاهره كفر وباطل، وأن ظاهره وحقائقه غير مرادة.', 'Дурное мнение о Всевышнем Господе выразилось в том, что она отвергла качества Его совершенства и приписала Ему ниспослание Книги, содержащей то, очевидный смысл чего — неверие и ложь, и утверждала, что её очевидный смысл и выраженные в ней реальности не подразумеваются.')])
